109	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
110	    workspace: &Workspace<'_, R, D>,
111	    release_commit: &CommitSha,
112	) -> Result<ReleaseDecisionV1, GraphError> {
113	    let head = git_stdout(workspace.runner, &workspace.root, &["rev-parse", "HEAD"])?;
114	    let head = CommitSha::parse(&head).map_err(|_error| GraphError::ReleaseIntentStale)?;
115	    if &head != release_commit {
116	        return Err(GraphError::ReleaseIntentStale);
117	    }
118	
119	    let parent_ref = format!("{}^", release_commit.as_str());
120	    let parent = git_stdout(workspace.runner, &workspace.root, &["rev-parse", &parent_ref])?;
121	    CommitSha::parse(&parent).map_err(|_error| GraphError::ReleaseIntentStale)?;
122	
123	    let changed = git_stdout(
124	        workspace.runner,
125	        &workspace.root,
126	        &[
127	            "diff-tree",
128	            "--no-commit-id",
129	            "--name-status",
130	            "-r",
131	            "--no-renames",
132	            &parent,
133	            release_commit.as_str(),
134	        ],
135	    )?;
136	    let changed = parse_name_status(&changed)?;
137	    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
138	    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
139	    let deleted_changesets = changed
140	        .iter()
141	        .filter_map(|(status, path)| {
142	            (status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md")).then_some(path)
143	        })
144	        .collect::<Vec<_>>();
145	    if deleted_changesets.is_empty() {
146	        return Err(GraphError::ReleaseIntentStale);
