                    if triggered_groups.contains(group) {
                        group_targets
                            .entry(group)
                            .or_default()
                            .push((package.id.clone(), after.clone()));
                    }
                }
                entries.push(ReleaseDecisionEntry {
                    package: id,
                    target_version: after,
                    reasons: vec![reason],
                });
